<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';
require_once __DIR__.'/../../config/db.php';
requireModuleAccess('customer_orders');
$id=(int)($_GET['id']??0);
$q=$conn->prepare("SELECT o.*,c.customer_name,c.phone,c.address,s.invoice_number,s.sale_date FROM customer_sales_orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN sales s ON s.id=o.sale_id WHERE o.id=? AND o.status='Invoiced'");
$q->execute([$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Confirmed customer order not found.');}
$q=$conn->prepare("SELECT i.*,p.product_name,p.sku,p.unit FROM customer_sales_order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=? ORDER BY i.id");$q->execute([$id]);$items=$q->fetchAll();
$company=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='company_name' LIMIT 1")->fetchColumn()?:'Dibonke Bookshop');
$deliveryAddress=(string)($o['address']??'');
?>
<!doctype html><html><head><meta charset="utf-8"><title>Delivery Note <?=e($o['order_number'])?></title><style>
*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#172b43;font:13px Arial,sans-serif}.actions{display:flex;justify-content:center;gap:10px;padding:16px}.actions a,.actions button{border:0;border-radius:6px;padding:10px 16px;background:#174a7e;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.sheet{width:210mm;min-height:297mm;margin:0 auto 20px;padding:17mm 16mm;background:#fff;box-shadow:0 2px 14px #0001}.top{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #174a7e;padding-bottom:18px}.top h1{font-size:25px;margin:0 0 7px}.top p{margin:4px 0;color:#64748b}.title{text-align:right}.title h2{font-size:25px;color:#174a7e;margin:0 0 8px}.details{display:grid;grid-template-columns:1fr 1fr;gap:25px;margin:25px 0}.eyebrow{font-size:10px;color:#64748b;font-weight:800;letter-spacing:1px;margin-bottom:8px}.details p{margin:5px 0;line-height:1.5}.items{width:100%;border-collapse:collapse;margin-top:20px}.items th{background:#17324d;color:#fff;text-align:left;padding:11px}.items td{padding:12px 10px;border-bottom:1px solid #e5eaf0}.num{text-align:right}.notice{margin-top:20px;padding:13px;background:#f3f7fb;border-left:4px solid #174a7e;color:#475569}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:90px}.signatures div{border-top:1px solid #64748b;padding-top:8px;color:#64748b}.footer{border-top:1px solid #dbe3ec;margin-top:45px;padding-top:12px;color:#64748b;font-size:10px;display:flex;justify-content:space-between}@page{size:A4;margin:0}@media print{body{background:#fff}.actions{display:none}.sheet{width:210mm;min-height:297mm;margin:0;padding:15mm;box-shadow:none}}</style></head><body>
<div class="actions"><button onclick="window.print()">Print A4 Delivery Note</button><a href="invoice.php?id=<?=$id?>">Back to Invoice</a></div>
<article class="sheet"><header class="top"><div><h1><?=e($company)?></h1><p>Books · Stationery · General Retail</p><p>Tel: 0706 046963</p></div><div class="title"><h2>DELIVERY NOTE</h2><strong><?=e($o['order_number'])?></strong><p>Invoice: <?=e($o['invoice_number'])?></p><p>Date: <?=e($o['sale_date'])?></p></div></header>
<section class="details"><div><div class="eyebrow">Deliver to</div><strong><?=e($o['customer_name'])?></strong><p><?=e($o['phone']??'')?></p><p><?=nl2br(e($deliveryAddress))?></p></div><div><div class="eyebrow">Dispatch reference</div><p><strong>Order:</strong> <?=e($o['order_number'])?></p><p><strong>Invoice:</strong> <?=e($o['invoice_number'])?></p><p><strong>Delivery date:</strong> __________________</p><p><strong>Delivery address confirmed:</strong> Yes / No</p></div></section>
<table class="items"><thead><tr><th style="width:8%">#</th><th>Item description</th><th style="width:22%">Quantity to deliver</th><th style="width:22%">Quantity received</th></tr></thead><tbody><?php foreach($items as $n=>$it):?><tr><td><?=$n+1?></td><td><strong><?=e($it['product_name'])?></strong><?php if(!empty($it['sku'])):?><br><small>SKU: <?=e($it['sku'])?></small><?php endif;?></td><td><?=e($it['entered_quantity'])?> <?=e($it['sale_unit'])?></td><td></td></tr><?php endforeach;?></tbody></table>
<div class="notice"><strong>Receiving note:</strong> Please check the quantities and condition of the goods before signing. Record any shortage, damage or discrepancy below.<br><br>Discrepancies: __________________________________________________________________________________</div>
<section class="signatures"><div>Dispatched by / Signature &amp; Date</div><div>Received by / Name, Signature &amp; Date</div></section><footer class="footer"><span>Goods supplied by <?=e($company)?></span><span><?=e($o['order_number'])?></span></footer></article></body></html>